import {analyse,historyKey} from './analytics.js';
import {followupFor} from './followups.js';
import {evaluateAnswer} from './rubrics.js';
import {cases, coaching} from './lessons.js';
import {book, matchReference, referenceFor, loadReferences, referenceStatus, referenceRevision} from './reference.js';
import * as pdfjs from './vendor/pdf.min.mjs';
pdfjs.GlobalWorkerOptions.workerSrc = './vendor/pdf.worker.min.mjs';
const $ = id => document.getElementById(id);
const state = {questions:[],index:0,answers:[],cv:'',listening:false,recognition:null,voiceMode:false,translated:'',translator:null,mode:'full',hasReport:false,currentView:'welcome',previousView:'welcome'};
const questions = [
  {en:'Please introduce yourself and tell us why you want to work in dentistry in {country}.',de:'Stellen Sie sich bitte vor und erklären Sie, warum Sie in {country} in der Zahnmedizin arbeiten möchten.',kind:'motivation'},
  {en:'Walk me through your clinical experience. Which responsibilities did you personally handle?',de:'Führen Sie uns durch Ihre klinische Erfahrung. Welche Aufgaben haben Sie persönlich übernommen?',kind:'cv'},
  {en:'Which dental procedures are you confident performing, and where would you seek support?',de:'Welche zahnärztlichen Behandlungen führen Sie sicher durch, und wobei würden Sie Unterstützung suchen?',kind:'clinical'},
  {en:'A patient arrives with acute dental pain. How would you assess urgency and explain your next steps?',de:'Ein Patient kommt mit akuten Zahnschmerzen. Wie beurteilen Sie die Dringlichkeit und erklären die nächsten Schritte?',kind:'safety'},
  {en:'How would you explain a treatment plan, its risks, alternatives, and costs to an anxious patient?',de:'Wie erklären Sie einem ängstlichen Patienten den Behandlungsplan, Risiken, Alternativen und Kosten?',kind:'communication'},
  {en:'Tell me about a difficult interaction with a patient or colleague. What did you do, and what did you learn?',de:'Erzählen Sie von einer schwierigen Situation mit einem Patienten oder Kollegen. Was haben Sie getan und gelernt?',kind:'team'},
  {en:'A patient refuses your recommended treatment. How do you respond?',de:'Ein Patient lehnt Ihre empfohlene Behandlung ab. Wie reagieren Sie?',kind:'ethics'},
  {en:'How do you handle infection prevention, documentation, and informed consent during a busy clinic day?',de:'Wie gehen Sie an einem vollen Praxistag mit Infektionsschutz, Dokumentation und Aufklärung um?',kind:'safety'},
  {en:'What is your current qualification or recognition status for working in {country}, and what steps are you taking?',de:'Wie ist der aktuelle Stand Ihrer Qualifikation oder Anerkennung für eine Tätigkeit in {country}, und welche Schritte unternehmen Sie?',kind:'cv'},
  {en:'What would you like to ask us about this position or our practice?',de:'Welche Fragen haben Sie an uns zu dieser Stelle oder zu unserer Praxis?',kind:'motivation'}
];
const specialist = {en:'Describe a challenging case in {specialty}. How did you plan care, manage risk, and decide when to refer?',de:'Beschreiben Sie einen anspruchsvollen Fall in {specialty}. Wie haben Sie die Behandlung geplant, Risiken berücksichtigt und über eine Überweisung entschieden?',kind:'clinical'};
const assistant = {en:'How do you prepare a treatment room and support both dentist and patient during a procedure?',de:'Wie bereiten Sie einen Behandlungsraum vor und unterstützen Zahnarzt und Patient während einer Behandlung?',kind:'team'};
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function clean(s){return String(s||'').replace(/\s+/g,' ').trim();}
function textFor(q,lang){return q[lang].replaceAll('{country}',clean($('country').value)||'Germany').replaceAll('{specialty}',clean($('specialty').value)||'your specialty');}
function stopVoice(){if(state.recognition){state.recognition.stop();state.recognition=null}state.listening=false;$('listen').textContent='🎙 Speak answer';if('speechSynthesis' in window) speechSynthesis.cancel()}
function availableVoices(){return 'speechSynthesis' in window?speechSynthesis.getVoices():[]}
function preferredEnglish(voices){return voices.find(v=>/^moira(?:\s|$)/i.test(v.name)&&/^en[-_]/i.test(v.lang))||voices.find(v=>/^en[-_]IE/i.test(v.lang)&&/natural|enhanced|premium|neural/i.test(v.name))||voices.find(v=>/^en[-_]IE/i.test(v.lang))||voices.find(v=>/^en[-_]/i.test(v.lang)&&/natural|enhanced|premium|neural/i.test(v.name))||voices.find(v=>/^en[-_]/i.test(v.lang))}
function utterance(text,lang){const u=new SpeechSynthesisUtterance(text);const voices=availableVoices();const voice=lang==='en'?preferredEnglish(voices):voices.find(v=>/^de[-_]/i.test(v.lang)&&/natural|enhanced|premium|neural/i.test(v.name))||voices.find(v=>/^de[-_]/i.test(v.lang));if(voice){u.voice=voice;u.lang=voice.lang}else u.lang=lang==='de'?'de-DE':'en-IE';u.rate=lang==='en'?.98:.95;u.pitch=1;return u}
function speak(){if(!('speechSynthesis' in window)){ $('voiceStatus').textContent='Spoken questions are unavailable in this browser.';return}speechSynthesis.cancel();const mode=$('language').value;const lines=(mode==='both'||mode==='en-to-de')?[['de',textFor(state.questions[state.index],'de')],['en',textFor(state.questions[state.index],'en')]]:[[mode,textFor(state.questions[state.index],mode)]];for(const [lang,text] of lines)speechSynthesis.speak(utterance(text,lang))}
const followupAngles=[
 {en:'What additional history or information would you seek before deciding?',de:'Welche zusätzlichen Angaben aus der Anamnese oder Untersuchung benötigen Sie vor einer Entscheidung?'},
 {en:'What risks or warning signs would change your priorities?',de:'Welche Risiken oder Warnzeichen würden Ihre Prioritäten ändern?'},
 {en:'How would you explain your reasoning and options to the patient or interviewer?',de:'Wie erklären Sie Ihre Überlegungen und Möglichkeiten der betroffenen Person oder im Bewerbungsgespräch?'},
 {en:'What would you document, and when would you seek support or refer?',de:'Was dokumentieren Sie, und wann holen Sie Unterstützung oder überweisen Sie?'},
 {en:'How would your plan change if the patient had a complex medical history?',de:'Wie würde sich Ihr Vorgehen bei einer komplexen medizinischen Vorgeschichte ändern?'},
 {en:'Give a concrete example from your own experience, or explain how you would approach it if you have none.',de:'Nennen Sie ein echtes Beispiel aus Ihrer Erfahrung oder erklären Sie Ihr Vorgehen, falls Sie keines haben.'}
];
function extendQuestions(){const base=state.questions.filter(q=>!q.followup);if(!base.length)return;const round=Math.floor((state.index-base.length)/base.length);const source=base[(state.index-base.length)%base.length];const angle=followupAngles[round%followupAngles.length];state.questions.push({...source,followup:true,title:source.title?`${source.title} · follow-up ${round+1}`:undefined,en:`Follow-up ${round+1}: ${textFor(source,'en')} ${angle.en}`,de:`Vertiefung ${round+1}: ${textFor(source,'de')} ${angle.de}`})}
function render(){state.currentView='session';$('latestPanel').classList.add('hidden');$('dashboard').classList.add('hidden');$('modePanel').classList.add('hidden');const q=state.questions[state.index];$('welcome').classList.add('hidden');$('report').style.display='none';$('session').classList.remove('hidden');$('bar').style.width='100%';$('counter').textContent=`QUESTION ${state.index+1} · CONTINUE UNTIL YOU STOP`; const mode=$('language').value;const bilingual=mode==='both'||mode==='en-to-de';$('prompt').textContent=textFor(q,mode==='en'?'en':'de');$('translation').textContent=bilingual?textFor(q,'en'):'';$('translation').hidden=!bilingual;$('prompt').lang=mode==='en'?'en':'de';$('translation').lang='en';$('translate').classList.toggle('hidden',mode!=='en-to-de');$('translated').classList.add('hidden');state.translated='';$('answer').value='';$('answer').focus();$('voiceStatus').textContent=state.voiceMode?'Question is spoken. Tap Speak answer when ready.':'';$('micHelp').classList.add('hidden');$('lesson').classList.add('hidden');}
function advance(skip=false){stopVoice();const answer=clean($('answer').value);if(!skip&&!answer){$('voiceStatus').textContent='Add an answer or choose Skip.';return}const current=state.questions[state.index];state.answers.push({question:current,answer,skipped:skip,translated:state.translated});if(!skip){const probe=followupFor(current,answer);if(probe)state.questions.splice(state.index+1,0,probe)}state.index++;if(state.index>=state.questions.length)extendQuestions();render();if(state.voiceMode)speak();}
function detectCv(text){const t=text.toLowerCase();const hits=[];for(const [term,label] of [['dentist','dentist'],['zahnärzt','Zahnärztin'],['clinic','clinic'],['klinik','clinic'],['hospital','hospital'],['zahnarzt','dental practice']])if(t.includes(term)&&!hits.includes(label))hits.push(label);return hits.slice(0,3)}
async function readCv(file){if(!file)return;const status=$('cvstatus');status.textContent='Reading CV…';try{let body='';if(/\.pdf$/i.test(file.name)){const pdf=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;for(let i=1;i<=Math.min(pdf.numPages,12);i++){let page=await pdf.getPage(i);let content=await page.getTextContent();body+=' '+content.items.map(x=>x.str).join(' ')}if(body.length<35)throw Error('This looks like a scanned PDF. Please upload a text-based PDF, DOCX, or TXT.')}else if(/\.docx$/i.test(file.name)){const zip=await window.JSZip.loadAsync(await file.arrayBuffer());const xml=await zip.file('word/document.xml')?.async('text');if(!xml)throw Error('Could not read the DOCX text.');const doc=new DOMParser().parseFromString(xml,'application/xml');body=[...doc.getElementsByTagNameNS('http://schemas.openxmlformats.org/wordprocessingml/2006/main','t')].map(n=>n.textContent).join(' ')}else if(/\.txt$/i.test(file.name))body=await file.text();else throw Error('Please choose PDF, DOCX, or TXT.');state.cv=clean(body).slice(0,30000);if(state.cv.length<30)throw Error('Could not extract enough text. Try a text-based CV.');status.textContent=`CV ready · ${detectCv(state.cv).join(', ')||'text extracted'}. Personal details will not be displayed.`}catch(e){state.cv='';status.textContent=e.message||'Could not read this file.'}}
function start(voice=false){stopVoice();state.voiceMode=voice;const role=$('role').value;state.questions=questions.map((q,i)=>({...q,rubricKey:['intro','experience','procedures','acute','communication','teamwork','refusal','safety','licensing','candidate'][i]}));if(role==='specialist'){state.questions.splice(3,0,{...specialist,rubricKey:'specialist'});if(!clean($('specialty').value)){document.querySelector('.setup').classList.add('settingsOpen');$('toggleSetup').textContent='Hide settings';$('toggleSetup').setAttribute('aria-expanded','true');$('specialty').focus();$('cvstatus').textContent='Enter the specialty to tailor this interview.';return}}if(role==='assistant')state.questions.splice(3,1,assistant);else state.questions.splice(4,0,...cases.map(q=>({...q})));const clinic=clean($('targetClinic').value);if(clinic){state.questions[0].en=`Please introduce yourself and explain why you are interested in ${clinic}.`;state.questions[0].de=`Stellen Sie sich vor und erklären Sie Ihr Interesse an ${clinic}.`}if(state.cv){const t=state.cv.toLowerCase();const hasGermany=t.includes('deutschland')||t.includes('germany');const hasGap=/20\d\d/.test(t);if(hasGap)state.questions.splice(2,0,{rubricKey:'timeline',en:'Your CV lists several roles and dates. Which roles overlapped, and how would you explain this timeline to an interviewer?',de:'Ihr Lebenslauf enthält mehrere Tätigkeiten und Zeiträume. Welche Tätigkeiten überschnitten sich und wie erklären Sie den zeitlichen Verlauf?',kind:'cv'});if(hasGermany)state.questions[0]={...state.questions[0],en:'Your CV mentions Germany. Please introduce yourself and explain your motivation for a dental role here.',de:'Ihr Lebenslauf erwähnt Deutschland. Stellen Sie sich bitte vor und erklären Sie Ihre Motivation für eine zahnmedizinische Tätigkeit hier.'};}const custom=clean($('customQuestion').value);if(state.mode==='cases'){const selected=$('caseSelect').value;state.questions=state.questions.filter(q=>q.kind==='case'&&(selected==='all'||q.title===selected))}if(state.mode==='hr'){const focus=$('hrFocus').value;const allowed=focus==='cv'?['intro','experience','timeline','licensing','candidate']:focus==='communication'?['communication','teamwork','refusal','candidate']:['intro','experience','timeline','communication','teamwork','refusal','candidate','licensing'];state.questions=state.questions.filter(q=>allowed.includes(q.rubricKey))}if(custom)state.questions.push({en:custom,de:custom,kind:'custom',rubricKey:'custom'});state.index=0;state.answers=[];render();if(state.voiceMode)speak()}
function sourceLinks(topic){return `${topic.page?`<span>Textbook background: ${escapeHTML(book.title)} (${book.year}), pp. ${escapeHTML(topic.page)}</span> · `:''}<a href="${topic.official}" target="_blank" rel="noopener noreferrer">Current reference: ${escapeHTML(topic.officialName)} ↗</a>`}
function personalNotes(){try{return JSON.parse(localStorage.getItem('dentalCoachPersonalNotes')||'[]')}catch{return []}}
$('saveNote').onclick=()=>{const topic=clean($('noteTopic').value),note=clean($('noteText').value),raw=$('noteSource').value.trim();if(!topic||!note){$('noteStatus').textContent='Add a topic and note.';return}let url='';if(raw){try{const parsed=new URL(raw);if(!['https:','http:'].includes(parsed.protocol))throw Error();url=parsed.href}catch{$('noteStatus').textContent='Enter a valid http or https source URL.';return}}try{localStorage.setItem('dentalCoachPersonalNotes',JSON.stringify([...personalNotes(),{topic,note,url}].slice(-20)));$('noteStatus').textContent='Saved on this device as an unverified personal note.';$('noteTopic').value='';$('noteText').value='';$('noteSource').value=''}catch{$('noteStatus').textContent='This browser could not save the note.'}};
function checkReference(){const query=clean($('referenceQuery').value);const box=$('referenceResults');if(!query){box.textContent='Enter a topic or question first.';return}if(referenceStatus!=='ready'){box.textContent='The shared knowledge pack is unavailable. No verified answer can be shown right now.';return}const matches=matchReference(query);const userNotes=personalNotes().filter(n=>query.toLowerCase().split(/\s+/).some(w=>w.length>3&&n.topic.toLowerCase().includes(w))).slice(-3);const noteHTML=userNotes.map(n=>`<div class="notice"><strong>Personal note · unverified · ${escapeHTML(n.topic)}</strong><p>${escapeHTML(n.note)}</p>${n.url?`<a href="${escapeHTML(n.url)}" target="_blank" rel="noopener noreferrer">Your source ↗</a>`:''}</div>`).join('');const lang=$('language').value==='de'?'de':'en';if(!matches.length){box.innerHTML='<p>No verified answer in this reference pack for that question. I will not invent one. Check an appropriate current professional source:</p><ul><li><a href="https://www.sdcep.org.uk/published-guidance/" target="_blank" rel="noopener noreferrer">SDCEP clinical guidance ↗</a></li><li><a href="https://www.bzaek.de/" target="_blank" rel="noopener noreferrer">German Dental Association (BZÄK) ↗</a></li></ul>'+noteHTML;return}box.innerHTML=matches.map(t=>`<div class="notice" style="margin:12px 0"><strong>${escapeHTML(t.id)}</strong><p>${escapeHTML(t[lang])}</p><small>Sources: ${sourceLinks(t)}</small></div>`).join('')+noteHTML}
loadReferences().then(()=>{$('referenceVersion').textContent=referenceRevision});
$('checkReference').onclick=checkReference;$('referenceQuery').addEventListener('keydown',e=>{if(e.key==='Enter')checkReference()});
function teach(format='full'){
 const q=state.questions[state.index];if(!q)return;
 const mode=$('language').value,bilingual=mode==='both'||mode==='en-to-de',lang=mode==='en'?'en':'de';
 const getPassage=l=>q.kind==='case'?(l==='de'?q.lessonDe:q.lessonEn):coaching[q.kind]?.[l];
 const isExperience=['cv','team','motivation','communication'].includes(q.kind),selected=['full','outline','star'].includes(format)?format:'full';
 const star={de:['Situation: Beschreiben Sie einen echten, konkreten Kontext.','Aufgabe: Nennen Sie Ihre eigene Verantwortung.','Handlung: Erklären Sie, was Sie persönlich getan haben.','Ergebnis: Schildern Sie das tatsächliche Ergebnis und was Sie gelernt haben.'],en:['Situation: Set the scene with a real example.','Task: State your own responsibility.','Action: Explain what you personally did.','Result: Give the actual outcome and what you learned.']};
 function guidance(l){const passage=getPassage(l)||(l==='de'?'Klären Sie die Situation, begründen Sie Ihr Vorgehen und erläutern Sie Patientensicherheit sowie nächste Schritte.':'Clarify the situation, explain your reasoning, include patient safety and next steps.');if(selected==='star'&&isExperience)return '<ol>'+star[l].map(item=>'<li>'+escapeHTML(item)+'</li>').join('')+'</ol>';if(selected==='outline'){const points=passage.match(/[^.!?]+[.!?]+|[^.!?]+$/g)?.map(part=>part.trim()).filter(Boolean).slice(0,4)||[passage];return '<ul>'+points.map(point=>'<li>'+escapeHTML(point)+'</li>').join('')+'</ul>'}return '<p>'+escapeHTML(passage)+'</p>'}
 const languages=bilingual?['de','en']:[lang];const box=$('lesson');box.classList.remove('hidden');
 box.innerHTML='<div class="teachingHead"><strong>Answer guidance / Antworthilfe</strong><label for="answerFormat">Format <select id="answerFormat"><option value="full">Full guidance / Ausführlich</option><option value="outline">Quick outline / Stichpunkte</option>'+(isExperience?'<option value="star">STAR framework / STAR-Methode</option>':'')+'</select></label></div>'+languages.map(l=>'<div class="guidanceLanguage"><strong>'+ (l==='de'?'Deutsch':'English')+'</strong>'+guidance(l)+'</div>').join('')+(selected==='star'?'<p class="muted">Nutzen Sie nur eigene, belegbare Beispiele. / Use only real examples you can verify.</p>':'')+(referenceFor(q)?'<p><strong>Reference check:</strong> '+languages.map(l=>'<span lang="'+l+'">'+escapeHTML(referenceFor(q)[l])+'</span>').join('<br>')+'</p><small>Sources: '+sourceLinks(referenceFor(q))+'</small>':'<p class="muted">'+(referenceStatus==='ready'?'No specific textbook passage verified for this question. Check a current professional source for clinical claims.':'The shared knowledge pack is unavailable; no source-backed answer can be shown.')+'</p>')+(q.source?'<a href="'+encodeURI(q.source)+'" target="_blank" rel="noopener noreferrer">Read clinical reference ↗</a>':'')+'<p class="muted" style="margin:10px 0 0">Interview practice only. Adapt to your own experience and local protocols.</p>';
 $('answerFormat').value=selected;$('answerFormat').onchange=e=>teach(e.target.value);
 if(state.voiceMode&&selected==='full'&&'speechSynthesis' in window){speechSynthesis.cancel();for(const l of languages){speechSynthesis.speak(utterance(getPassage(l),l))}}
}
async function translateAnswer(){
 const source=clean($('answer').value), out=$('translated');
 if(!source){$('voiceStatus').textContent='Speak or type an English answer first.';return}
 out.classList.remove('hidden');out.textContent='Preparing Deutsch translation…';
 if(!('Translator' in self)){out.textContent='Translation is unavailable in this browser. The Deutsch example answer is available under Teach me. On desktop, try a recent Chrome browser in a normal tab.';return}
 try{
  const availability=await Translator.availability({sourceLanguage:'en',targetLanguage:'de'});
  if(availability==='unavailable')throw Error('This browser cannot translate English to Deutsch.');
  if(!state.translator)state.translator=await Translator.create({sourceLanguage:'en',targetLanguage:'de',monitor(m){m.addEventListener('downloadprogress',e=>out.textContent=`Downloading Deutsch language pack: ${Math.round(e.loaded*100)}%`)}});
  const translated=await state.translator.translate(source);
  state.translated=translated;out.innerHTML='<strong>Deutsch translation</strong><p style="margin:8px 0 0">'+escapeHTML(translated)+'</p>';
  if('speechSynthesis' in window){speechSynthesis.cancel();speechSynthesis.speak(utterance(translated,'de'))}
 }catch(e){out.textContent=`Translation could not start: ${e.message||'browser error'}. Use Teach me for a Deutsch example answer.`}
}
function reviewAnswer(a){return evaluateAnswer(a.answer,a.question.rubricKey||a.question.title||a.question.kind)}
function scoreAnswer(a){return a.skipped?0:reviewAnswer(a).score}
function finish(early=false){stopVoice();state.currentView='report';state.previousView='report';$('latestPanel').classList.add('hidden');$('dashboard').classList.add('hidden');$('modePanel').classList.add('hidden');if(early){const answer=clean($('answer').value);if(answer)state.answers.push({question:state.questions[state.index],answer,skipped:false,translated:state.translated})}$('session').classList.add('hidden');$('welcome').classList.add('hidden');const report=$('report');report.style.display='block';state.hasReport=true;$('navReport').disabled=false;const graded=state.answers.filter(x=>!x.skipped);const total=Math.round(state.answers.reduce((sum,a)=>sum+scoreAnswer(a),0)/Math.max(1,state.answers.length)*10);$('score').textContent=total;let name=clean($('name').value);$('assessment').textContent=`${name?name+' · ':''}${early?'Interview stopped. ':''}${!state.answers.length?'No answers were submitted, so there is no interview performance to assess.':total>=80?'Strong practice answers. Refine examples and precision.':total>=60?'Good foundation. Add clearer examples and patient-safety detail.':'More practice needed. Give fuller answers with concrete examples.'} This is a keyword-based practice coverage score, not a clinical competence or language certification score.`;
 const outcome=early?(state.answers.length?'Interview score':'No answers to score'):total>=85?'Strong practice performance':total>=70?'Nearly ready for a practice interview':total>=50?'More targeted practice recommended':'Build the core answers first';
 $('outcome').textContent=outcome;
 $('donut').style.setProperty('--pct',`${total}%`);
 const labelFor=(a,i)=>a?.question?.title||({motivation:'Motivation',cv:'CV & experience',clinical:'Clinical reasoning',safety:'Patient safety',communication:'Patient communication',team:'Teamwork',ethics:'Professional judgment'}[a?.question?.kind]||`Question ${i+1}`);
 $('questionChart').innerHTML='<h3>Score by question</h3>'+state.answers.map((a,i)=>{const q=a.question;const n=scoreAnswer(a);const label=`Q${i+1} · ${labelFor(a,i)}`;return `<div class="chartRow" title="${escapeHTML(textFor(q,$('language').value==='de'?'de':'en'))}"><span class="chartLabel">${escapeHTML(label)}</span><div class="chartTrack" role="meter" aria-label="${escapeHTML(label)}" aria-valuemin="0" aria-valuemax="10" aria-valuenow="${n}"><span class="chartFill ${n<5?'low':n<7?'mid':''}" style="width:${n*10}%"></span></div><span class="chartValue">${n}/10</span></div>`}).join('')+`<p class="chartNote">${state.answers.length} questions reached. The overall score uses only questions reached; skipped questions score 0. Scoring detects words related to each rubric point and shows the matching excerpt. It does not verify whether statements are clinically correct or assess pronunciation.</p>`;
 const brief=graded.filter(a=>scoreAnswer(a)>=7).length;const skipped=state.answers.length-graded.length;const weak=state.answers.filter(a=>scoreAnswer(a)<6);const safety=state.answers.filter(a=>['safety','ethics','clinical'].includes(a.question.kind)&&scoreAnswer(a)<7);
 $('feedback').innerHTML=`<h3>What came through</h3><ul><li>${brief} answers had useful detail or relevant professional terms.</li><li>${graded.length} of ${state.answers.length} reached questions answered${skipped?`; ${skipped} skipped`:''}.</li></ul><h3>What to improve</h3><ul><li>${weak.length?'Expand short answers: state what you did, why, and what happened.':'Keep your specific examples concise and tied to the question.'}</li><li>${safety.length?'Revisit urgency, informed consent, documentation, referral, and patient safety where relevant.':'Keep patient safety and informed consent explicit in clinical scenarios.'}</li><li>Confirm that any qualification, scope of practice, and licensing statements match your documents and the relevant authority.</li></ul><h3>Practice plan</h3><ul><li>Today: rehearse your introduction and two CV examples aloud.</li><li>This week: practise one clinical and one patient communication scenario daily.</li><li>This month: repeat a full interview and compare your answers for specificity and clarity.</li></ul><p class="muted" style="margin-top:16px">Automated feedback checks question-specific points in your answer. It cannot verify clinical correctness, pronunciation, legal eligibility, or the truth of CV claims.</p>`;
 $('transcript').innerHTML='<h3>Questions and answers</h3>'+state.answers.map((a,i)=>`<details><summary>${i+1}. ${escapeHTML(textFor(a.question,$('language').value==='de'?'de':'en'))} · ${scoreAnswer(a)}/10</summary><p>${escapeHTML(a.answer||'Skipped')}</p>${a.translated?'<p><strong>Deutsch:</strong> '+escapeHTML(a.translated)+'</p>':''}<p><strong>Assessment:</strong> ${escapeHTML(reviewAnswer(a).summary)}</p><p><strong>Rubric points detected:</strong> ${escapeHTML(reviewAnswer(a).covered.join(', ')||'None detected')}</p>${reviewAnswer(a).evidence?.length?'<ul>'+reviewAnswer(a).evidence.map(e=>'<li><strong>'+escapeHTML(e.criterion)+':</strong> “'+escapeHTML(e.excerpt)+'”</li>').join('')+'</ul>':''}<p><strong>Improve:</strong> ${escapeHTML(reviewAnswer(a).tips.join(' ')||'Check clinical accuracy and add a genuine example if relevant.')}</p><p class="muted"><strong>Example approach:</strong> ${escapeHTML(a.question.kind==='case'?(a.question.lessonEn||''):(coaching[a.question.kind]?.en||''))}</p>${referenceFor(a.question)?`<div class="notice"><strong>Source-backed study point (not a verification of your answer):</strong><p>${escapeHTML(referenceFor(a.question)[$('language').value==='en'?'en':'de'])}</p><small>${sourceLinks(referenceFor(a.question))}</small></div>`:a.question.kind==='case'||a.question.kind==='clinical'||a.question.kind==='safety'?'<p class="muted">No reviewed passage is mapped to this question; clinical accuracy was not assessed.</p>':''}</details>`).join('');saveLatest(total,early);report.scrollIntoView({behavior:'smooth',block:'start'});}
async function listen(){
 const msg=$('voiceStatus'), help=$('micHelp');
 if(state.listening){state.recognition?.stop();return}
 help.classList.add('hidden');
 const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;
 if(!SpeechRecognition){msg.textContent='Speech recognition is unavailable in this browser. Try Chrome or Edge, or type your answer.';return}
 if(!window.isSecureContext){msg.textContent='Microphone access needs a secure HTTPS page. Open the site in a new tab.';help.classList.remove('hidden');return}
 if(!navigator.mediaDevices?.getUserMedia){msg.textContent='Microphone access is unavailable here. Open this site in a normal browser tab.';help.classList.remove('hidden');return}
 if('speechSynthesis' in window)speechSynthesis.cancel();
 try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});stream.getTracks().forEach(t=>t.stop())}
 catch(e){msg.textContent=e.name==='NotAllowedError'||e.name==='SecurityError'?'The browser blocked microphone access. Update this site’s microphone permission, then retry.':e.name==='NotFoundError'?'No microphone was found. Connect one or type your answer.':`Microphone could not start (${e.name||'device error'}). Try another input device or type your answer.`;if(e.name==='NotAllowedError'||e.name==='SecurityError')help.classList.remove('hidden');return}
 const rec=new SpeechRecognition();state.recognition=rec;
 rec.lang=$('language').value==='de'?'de-DE':'en-US';rec.continuous=true;rec.interimResults=true;
 const previous=$('answer').value;let final='';
 rec.onresult=e=>{let interim='';for(let i=e.resultIndex;i<e.results.length;i++){const phrase=e.results[i][0].transcript;if(e.results[i].isFinal){if(/^(teach me|help me|erkläre es|lehr mich)\W*$/i.test(phrase.trim())){rec.stop();teach();return}final+=phrase+' '}else interim+=phrase}$('answer').value=(previous+' '+final+interim).trim()};
 rec.onerror=e=>{if(e.error==='not-allowed'||e.error==='service-not-allowed'){msg.textContent='Microphone access or the browser speech service was blocked. Check this site’s permission, reload, and retry.';help.classList.remove('hidden')}else msg.textContent=`Speech recognition stopped (${e.error}). You can type your answer.`};
 rec.onend=()=>{state.listening=false;state.recognition=null;$('listen').textContent='🎙 Speak answer';if(!msg.textContent)msg.textContent='Recording stopped. Review your answer before submitting.';if($('language').value==='en-to-de'&&clean($('answer').value))translateAnswer()};
 try{rec.start();state.listening=true;$('listen').textContent='■ Stop recording';msg.textContent='Listening… Speak naturally, then stop recording.'}catch(e){msg.textContent=`Speech recognition could not start (${e.name||'browser error'}). Try again or type your answer.`}
}
$('toggleSetup').onclick=()=>{const opened=document.querySelector('.setup').classList.toggle('settingsOpen');$('toggleSetup').textContent=opened?'Hide settings':'Edit settings';$('toggleSetup').setAttribute('aria-expanded',String(opened))};
$('role').onchange=()=>{$('specialtyField').hidden=$('role').value!=='specialist'};$('cv').onchange=e=>readCv(e.target.files[0]);$('modeStartText').onclick=()=>start(false);$('modeStartVoice').onclick=()=>start(true);$('next').onclick=()=>advance();$('skip').onclick=()=>advance(true);$('stopInterview').onclick=()=>finish(true);$('speak').onclick=speak;$('repeat').onclick=speak;$('listen').onclick=listen;$('teach').onclick=teach;$('translate').onclick=translateAnswer;$('answer').addEventListener('input',()=>{state.translated='';$('translated').classList.add('hidden')});$('print').onclick=()=>window.print();$('restart').onclick=()=>{stopVoice();state.index=0;state.answers=[];state.currentView='welcome';state.previousView='welcome';$('report').style.display='none';$('welcome').classList.remove('hidden');$('modePanel').classList.remove('hidden');window.scrollTo({top:0,behavior:'smooth'})};

const modeContent={
 full:{title:'Full interview',description:'An open-ended interview with CV questions, clinical cases, communication and professional judgment.',eyebrow:'FULL INTERVIEW',welcome:'A complete interview, at your pace.',body:'Practise across all topics. Your answers receive question-by-question feedback when you stop.',voice:'🎙 Start full voice interview',text:'Start full text interview'},
 cases:{title:'Clinical cases',description:'Choose a patient history below, then practise assessment, safety and communication.',eyebrow:'CLINICAL CASES',welcome:'Work through a patient history.',body:'Pick one clinical scenario or all four. Explain your assessment, risks, patient communication and next steps.',voice:'🎙 Start clinical voice cases',text:'Start clinical text cases'},
 hr:{title:'HR practice',description:'Choose your HR focus below, then practise CV, motivation, communication and teamwork.',eyebrow:'HR PRACTICE',welcome:'Practise the people-side questions.',body:'Choose a focus, give specific examples from your real experience and get feedback when you stop.',voice:'🎙 Start HR voice practice',text:'Start HR text practice'}
};
function selectMode(mode){
 const info=modeContent[mode];if(!info)return;
 state.mode=mode;
 document.querySelectorAll('.modeTab').forEach(b=>{const active=b.dataset.mode===mode;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});
 $('modeHeading').textContent=info.title;$('modeDescription').textContent=info.description;
 $('welcomeEyebrow').textContent=info.eyebrow;$('welcomeTitle').textContent=info.welcome;$('welcomeDescription').textContent=info.body;
 $('modeStartVoice').textContent=info.voice;$('modeStartText').textContent=info.text;
 $('caseControls').classList.toggle('hidden',mode!=='cases');$('hrControls').classList.toggle('hidden',mode!=='hr');
 if(state.currentView==='welcome')$('modePanel').classList.remove('hidden');
}
function navigateMode(mode,updateUrl=true){
 if(!modeContent[mode])return;
 if(state.currentView==='session'&&state.mode===mode){$('session').scrollIntoView({behavior:'smooth',block:'start'});return}
 if(state.currentView==='session'){
  if(state.answers.length||clean($('answer').value))finish(true);
  else stopVoice();
 }
 state.index=0;state.answers=[];state.translated='';state.currentView='welcome';state.previousView='welcome';
 $('session').classList.add('hidden');$('latestPanel').classList.add('hidden');$('dashboard').classList.add('hidden');$('report').style.display='none';
 $('welcome').classList.remove('hidden');$('modePanel').classList.remove('hidden');
 $('navInterview').classList.add('active');$('navReport').classList.remove('active');$('navDashboard').classList.remove('active');
 selectMode(mode);
 if(updateUrl&&location.hash!==`#${mode}`)history.pushState({mode},'',`#${mode}`);
 $('modePanel').scrollIntoView({behavior:'smooth',block:'start'});
}
document.querySelectorAll('.modeTab').forEach(b=>b.onclick=()=>navigateMode(b.dataset.mode));
window.addEventListener('popstate',()=>navigateMode(location.hash.slice(1)||'full',false));
function sessionHistory(){try{const list=JSON.parse(localStorage.getItem(historyKey)||'[]');return Array.isArray(list)?list.filter(s=>Array.isArray(s.results)).slice(-30):[]}catch{return []}}
function saveLatest(total,early){
 const saved={date:new Date().toISOString(),name:clean($('name').value),mode:state.mode,total,early,completed:state.answers.length,planned:state.answers.length,results:state.answers.map((a,i)=>({question:textFor(a.question,$('language').value==='de'?'de':'en'),score:scoreAnswer(a),summary:reviewAnswer(a).summary,tips:reviewAnswer(a).tips,missing:reviewAnswer(a).missing,kind:a.question.kind,title:a.question.title||'',skipped:a.skipped,sourceMapped:!!referenceFor(a.question)}))};
 try{localStorage.setItem('dentalCoachLatestReport',JSON.stringify(saved));if(saved.results.length)localStorage.setItem(historyKey,JSON.stringify([...sessionHistory(),saved].slice(-30)));state.hasReport=true;$('navReport').disabled=false}catch{}
}
function renderDashboard(){
 const sessions=sessionHistory(),box=$('dashboardContent');
 if(!sessions.length){box.innerHTML='<div class="dashboardEmpty"><h3>No practice sessions yet</h3><p>Finish or stop an interview to start tracking your progress on this device.</p><button type="button" class="button" id="dashboardStart">Start practice</button></div>';$('dashboardStart').onclick=()=>navigateMode('full');return}
 const data=analyse(sessions);const latest=sessions.at(-1),points=data.trend;
 const svg=points.map((p,i)=>`${points.length===1?50:6+i*88/(points.length-1)},${100-p.score}`).join(' ');
 const chart=`<svg class="dashboardTrend" viewBox="0 0 100 105" role="img" aria-label="Practice score trend for ${points.length} sessions" preserveAspectRatio="none"><path d="M 0 100 H 100" stroke="#cbdcdd" fill="none"/><polyline points="${svg}" fill="none" stroke="#087d82" stroke-width="2" vector-effect="non-scaling-stroke"/>${points.map((p,i)=>`<circle cx="${points.length===1?50:6+i*88/(points.length-1)}" cy="${100-p.score}" r="1.6" fill="#087d82"><title>${escapeHTML(new Date(p.date).toLocaleDateString())}: ${p.score}/100, ${p.count} questions, ${escapeHTML(p.mode)}</title></circle>`).join('')}</svg>`;
 const weak=data.topics.slice().sort((a,b)=>a.score-b.score)[0];
 box.innerHTML=`<div class="dashboardStats"><div class="dashboardStat"><strong>${sessions.length}</strong><span>Sessions saved</span></div><div class="dashboardStat"><strong>${data.answered}</strong><span>Answers practised</span></div><div class="dashboardStat"><strong>${data.skipped}</strong><span>Questions skipped</span></div></div><div class="dashboardGrid"><section class="dashboardCard"><h3>Performance by topic</h3>${data.topics.map(t=>`<div class="dashboardRow"><span>${escapeHTML(t.name)}</span><div class="dashboardTrack" role="meter" aria-label="${escapeHTML(t.name)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${t.score}"><i style="width:${t.score}%"></i></div><strong>${t.score}%</strong></div>`).join('')}<p class="muted">Average rubric coverage across ${data.answered+data.skipped} reached questions. Tap Latest report for question detail.</p></section><section class="dashboardCard"><h3>Progress over time</h3>${chart}<div class="dashboardTrendLabel"><span>${escapeHTML(new Date(points[0].date).toLocaleDateString())}</span><span>${escapeHTML(new Date(points.at(-1).date).toLocaleDateString())}</span></div><p class="muted">Last ${points.length} sessions · different modes and question counts may not be directly comparable.</p></section><section class="dashboardCard"><h3>Improvement priorities</h3>${data.priorities.length?data.priorities.map(p=>`<div class="dashboardPriority"><strong>${escapeHTML(p.point)}</strong><small>Missed in ${p.count} answer${p.count===1?'':'s'}</small></div>`).join(''):'<p>No missing points detected yet. Check the accuracy of your answers against the cited guidance.</p>'}<p class="muted">Rubric checks detect wording, not factual correctness.</p></section><section class="dashboardCard"><h3>Suggested next practice</h3><p>${weak?`Your lowest covered topic is <strong>${escapeHTML(weak.name)}</strong> (${weak.score}% across ${weak.count} questions). Practise that area again and compare your answer detail.`:'Try a full interview to build a topic breakdown.'}</p><button type="button" class="button dashboardAction" id="dashboardRetry">${weak?'Practise '+escapeHTML(weak.name):'Start full interview'}</button><p class="muted" style="margin-top:14px">Clinical source summaries mapped to ${data.sourceMapped} answers. ${data.sourceUnmapped} clinical/safety answers had no mapped source. Mapping does not verify your claims.</p></section></div><p class="hint" style="margin-top:16px">History stays in this browser (up to 30 sessions). It stores scores and missed points, not CV text or full answers. The latest report remains available separately.</p>`;
 $('dashboardRetry').onclick=()=>{const mode=weak?.name==='Clinical cases'?'cases':['Communication','CV and HR'].includes(weak?.name)?'hr':'full';navigateMode(mode);if(mode==='hr')$('hrFocus').value=weak?.name==='Communication'?'communication':'cv';if(mode==='cases'){const recent=latest.results?.find(r=>r.kind==='case'&&r.score<7&&r.title);$('caseSelect').value=recent?.title||'all'}};
}
function renderLatest(){let item;try{item=JSON.parse(localStorage.getItem('dentalCoachLatestReport')||'null')}catch{}if(!item){$('latestContent').textContent='No completed interview report is saved on this device yet.';return}const when=new Date(item.date).toLocaleString();$('latestContent').innerHTML=`<div class="latestScore">${Number(item.total)||0}/100</div><p class="latestMeta">${escapeHTML(item.name||'Candidate')} · ${escapeHTML(item.mode||'full')} · ${escapeHTML(when)} · ${item.completed} questions reached · stopped by candidate</p>`+item.results.map((r,i)=>`<div class="latestRow"><strong>Q${i+1} · ${Number(r.score)||0}/10</strong><p>${escapeHTML(r.question)}</p><p>${escapeHTML(r.summary)}</p><p class="muted">${escapeHTML(r.tips?.join(' ')||'Review the answer for accuracy.')}</p></div>`).join('')+'<p class="hint">Saved locally on this device. The original answers and CV were not stored.</p>'}
function showInterview(){const view=state.previousView==='dashboard'?'report':state.previousView||'welcome';$('latestPanel').classList.add('hidden');$('dashboard').classList.add('hidden');$('navInterview').classList.add('active');$('navReport').classList.remove('active');$('navDashboard').classList.remove('active');$('session').classList.toggle('hidden',view!=='session');$('welcome').classList.toggle('hidden',view!=='welcome');$('report').style.display=view==='report'?'block':'none';$('modePanel').classList.toggle('hidden',view!=='welcome');state.currentView=view;window.scrollTo({top:0,behavior:'smooth'})}
$('navInterview').onclick=showInterview;
$('backInterview').onclick=showInterview;
$('navDashboard').onclick=()=>{if(state.currentView==='session'){if(state.answers.length||clean($('answer').value))finish(true);else stopVoice()}state.previousView=state.currentView==='dashboard'?state.previousView:state.currentView;renderDashboard();$('dashboard').classList.remove('hidden');$('latestPanel').classList.add('hidden');$('session').classList.add('hidden');$('welcome').classList.add('hidden');$('report').style.display='none';$('modePanel').classList.add('hidden');state.currentView='dashboard';$('navDashboard').classList.add('active');$('navInterview').classList.remove('active');$('navReport').classList.remove('active');$('dashboard').scrollIntoView({behavior:'smooth'})};

$('navReport').onclick=()=>{if(!state.hasReport)return;state.previousView=['latest','dashboard'].includes(state.currentView)?state.previousView:state.currentView;renderLatest();$('latestPanel').classList.remove('hidden');$('dashboard').classList.add('hidden');$('session').classList.add('hidden');$('welcome').classList.add('hidden');$('report').style.display='none';$('modePanel').classList.add('hidden');state.currentView='latest';$('navReport').classList.add('active');$('navInterview').classList.remove('active');$('navDashboard').classList.remove('active');$('latestPanel').scrollIntoView({behavior:'smooth'})};
let storedReport;try{storedReport=JSON.parse(localStorage.getItem('dentalCoachLatestReport')||'null')}catch{}state.hasReport=!!storedReport;$('navReport').disabled=!state.hasReport;selectMode(modeContent[location.hash.slice(1)]?location.hash.slice(1):'full');
